/* Docs library: admins upload .txt/.md/.csv/.html files (or write a doc from
   scratch) and everyone sees them on the Docs tab as cards. Text docs show
   the raw lines plus auto-detected clickable link tiles; HTML docs get a
   "single-file page" view that opens the page in a fresh about:blank tab.
   Self-contained, mirrors partners.js (same admin gate + localStorage). */
(function () {
  "use strict";

  var STORE_KEY = "chalkle.docs.v1";
  var MAX_DOCS = 200;
  var MAX_TEXT_BYTES = 1.5 * 1024 * 1024; /* per-file cap so localStorage stays happy */
  var ADMIN_KEY = "chalkle-admin-unlocked"; /* same key app.js uses for the admin panel */
  var FILTER_KEY = "chalkle-docs-filter"; /* persisted docs type filter (all|list|svg|html) */

  var state = { docs: [], filter: "all" };

  function isAdmin() {
    try { return localStorage.getItem(ADMIN_KEY) === "1"; } catch (e) { return false; }
  }

  /* ---------- persistence ---------- */

  function load() {
    try {
      var raw = localStorage.getItem(STORE_KEY);
      if (!raw) return;
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) state.docs = parsed;
    } catch (e) {
      state.docs = [];
    }
  }

  function save() {
    try {
      var json = JSON.stringify(state.docs);
      if (json.length > 5 * 1024 * 1024) {
        var copy = state.docs.slice().sort(function (a, b) {
          return String(b.content || "").length - String(a.content || "").length;
        });
        while (copy.length && json.length > 5 * 1024 * 1024) {
          copy.pop();
          json = JSON.stringify(copy);
        }
        state.docs = copy;
      }
      localStorage.setItem(STORE_KEY, json);
    } catch (e) {
      notice("Storage full. Remove a doc or two.");
    }
  }

  /* ---------- helpers ---------- */

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function timeAgo(ts) {
    var diff = Date.now() - ts;
    if (diff < 60 * 1000) return "just now";
    if (diff < 3600 * 1000) return Math.floor(diff / 60000) + "m ago";
    if (diff < 86400 * 1000) return Math.floor(diff / 3600000) + "h ago";
    return Math.floor(diff / 86400000) + "d ago";
  }

  function linkCount(content) {
    var m = String(content || "").match(/https?:\/\/[^\s<>"']+/g);
    return m ? m.length : 0;
  }

  function isHtmlDoc(content) {
    var t = String(content || "").trim().toLowerCase();
    return t.indexOf("<!doctype html") === 0 ||
           t.indexOf("<html") === 0 ||
           t.indexOf("<head") === 0 ||
           t.indexOf("<body") === 0 ||
           (/<html[\s>]/i.test(t)) && t.indexOf("</html>") !== -1;
  }

  /* SVG cloak files embed an HTML page via <foreignObject> (or an iframe +
     script). They open in a new tab just like an HTML doc, so treat them as
     pages: anything that starts as an SVG document and contains <svg>.</svg>. */
  function isSvgDoc(content) {
    var t = String(content || "").trim();
    if (!t) return false;
    var low = t.toLowerCase();
    return (low.indexOf("<svg") === 0 || low.indexOf("<?xml") === 0) &&
           low.indexOf("<svg") !== -1 && low.indexOf("</svg>") !== -1;
  }

  /* Link-list viewer docs (Cherri List, Crazy Cats, Noahs Tutoring Hub) are
     marked with the list flag by their seed. They're HTML pages internally but
     are presented as "lists", not HTML pages. */
  function isListDoc(doc) {
    return !!(doc && doc.list);
  }

  /* Bucket every doc into a filterable type: list / svg / html / text.
     List docs are checked first because they're HTML pages internally but are
     presented as link lists. */
  function docType(doc) {
    if (isListDoc(doc)) return "list";
    if (isSvgDoc(doc.content)) return "svg";
    if (isHtmlDoc(doc.content)) return "html";
    return "text";
  }

  function extractLinks(content) {
    var out = [];
    var seen = {};
    var re = /https?:\/\/[^\s<>"']+/g;
    var m;
    while ((m = re.exec(String(content || ""))) !== null) {
      var url = m[0].replace(/[),.;!?]+$/, "");
      if (!seen[url]) { seen[url] = 1; out.push(url); }
    }
    return out;
  }

  function linesOf(content) {
    return String(content || "").split(/\r?\n/).filter(function (l) {
      return l.trim().length > 0;
    });
  }

  function sortedDocs() {
    var sort = document.getElementById("docs-sort");
    var mode = sort ? sort.value : "new";
    var docs = state.docs.slice();
    if (state.filter !== "all") {
      docs = docs.filter(function (d) { return docType(d) === state.filter; });
    }
    var TYPE_ORDER = { list: 0, html: 1, svg: 2, text: 3 };
    docs.sort(function (a, b) {
      switch (mode) {
        case "az": return String(a.title || "").localeCompare(b.title || "");
        case "za": return String(b.title || "").localeCompare(a.title || "");
        case "links": return linkCount(b.content) - linkCount(a.content);
        default:
          /* Default view: group by kind first so the page reads link lists,
             then HTML pages, then SVGs (newest first inside each group)
             instead of interleaving them by upload time. */
          var ta = TYPE_ORDER[docType(a)];
          var tb = TYPE_ORDER[docType(b)];
          if (ta !== tb) return ta - tb;
          return (b.created || 0) - (a.created || 0);
      }
    });
    return docs;
  }

  /* ---------- notice toast (mirrors partners.js) ---------- */

  function notice(msg) {
    var box = document.getElementById("toast-box");
    if (!box) return;
    var t = el("div", "toast", msg);
    box.appendChild(t);
    setTimeout(function () { t.classList.add("is-out"); }, 2200);
    setTimeout(function () { if (t.parentNode) t.parentNode.removeChild(t); }, 2700);
  }

  /* ---------- rendering: Docs tab ---------- */

  function render() {
    var grid = document.getElementById("docs-grid");
    var count = document.getElementById("docs-count");
    var empty = document.getElementById("docs-empty");
    var bar = document.querySelector(".docs-bar");
    var hint = empty ? empty.querySelector("[data-docs-hint]") : null;
    if (!grid) return;

    var docs = sortedDocs();
    grid.innerHTML = "";

    /* Keep the type-filter chips in sync: active state + per-type counts. */
    var filterBtns = document.querySelectorAll("[data-docs-filter]");
    for (var fi = 0; fi < filterBtns.length; fi++) {
      var fbtn = filterBtns[fi];
      var fval = fbtn.dataset.docsFilter || "all";
      fbtn.classList.toggle("is-active", fval === state.filter);
      if (fval !== "all") {
        var n = state.docs.filter(function (d) { return docType(d) === fval; }).length;
        fbtn.textContent = fval.charAt(0).toUpperCase() + fval.slice(1) + " (" + n + ")";
      }
    }

    if (count) {
      count.textContent = state.filter !== "all"
        ? docs.length + " of " + state.docs.length + (state.docs.length === 1 ? " doc" : " docs")
        : docs.length + (docs.length === 1 ? " doc" : " docs");
    }
    if (empty) empty.hidden = docs.length > 0;
    if (bar) bar.hidden = !isAdmin();

    if (hint) {
      hint.textContent = isAdmin()
        ? "Add real docs (txt/md/html/svg) with the upload bar above - they show up here."
        : "Only admins can add docs. You can still open, download, and copy what is here.";
    }

    docs.forEach(function (doc) {
      var html = isHtmlDoc(doc.content);
      var svg = isSvgDoc(doc.content);
      var page = html || svg;
      var isList = isListDoc(doc);
      var links = extractLinks(doc.content);
      var card = el("div", "docs-card");
      card.dataset.id = doc.id;

      var head = el("div", "docs-card-head");
      var titleRow = el("div", "docs-card-title-row");
      var title = el("div", "docs-card-title", doc.title || "Untitled");
      var chipLabel = isList
        ? (doc.count ? formatCount(doc.count) + " links" : "List")
        : (page ? (svg ? "SVG page" : "HTML page") : (links.length + " links"));
      var chip = el("span", "docs-meta-chip", chipLabel);
      if (isList) chip.classList.add("is-list");
      else if (page) chip.classList.add("is-html");
      titleRow.appendChild(title);
      titleRow.appendChild(chip);
      head.appendChild(titleRow);

      var meta = el("div", "docs-card-meta");
      meta.appendChild(el("span", "docs-meta-time", timeAgo(doc.created || Date.now())));
      if (doc.created && doc.content) {
        meta.appendChild(el("span", "docs-meta-size", formatBytes(String(doc.content).length)));
      }
      head.appendChild(meta);

      var actions = el("div", "docs-card-actions");
      actions.appendChild(actionBtn("Open as page", "open", function () { openDocPage(doc.id); }));
      actions.appendChild(actionBtn("Download", "down", function () { downloadDoc(doc.id); }));
      actions.appendChild(actionBtn("Copy all", "copy", function () { copyDoc(doc.id); }));
      if (isAdmin()) {
        actions.appendChild(actionBtn("Edit", "edit", function () { editDoc(doc.id); }));
        actions.appendChild(actionBtn("Delete", "del", function () { deleteDoc(doc.id); }));
      }
      head.appendChild(actions);

      card.appendChild(head);

      var body = el("div", "docs-card-body-wrap");
      var inner = el("div", "docs-body");

      if (page || isList) {
        var htmlLine = el("div", "docs-line html-note");
        htmlLine.textContent = isList
          ? "This is a searchable link list. Open it as a page to browse, search, and open the links."
          : svg
          ? "This is a single-file SVG cloak page. Open it in a fresh tab - no server needed."
          : "This is a single-file HTML page. Open it in a fresh about:blank tab - no server needed.";
        inner.appendChild(htmlLine);
      } else {
        var shown = linesOf(doc.content).slice(0, 6);
        shown.forEach(function (l) {
          var line = el("div", "docs-line", l.length > 160 ? l.slice(0, 160) + "\u2026" : l);
          inner.appendChild(line);
        });
        if (linesOf(doc.content).length > 6) {
          inner.appendChild(el("div", "docs-line is-more", "\u2026 " + (linesOf(doc.content).length - 6) + " more lines"));
        }
      }

      if (links.length) {
        var linksWrap = el("div", "docs-links");
        links.slice(0, 6).forEach(function (url) {
          var a = el("a", "docs-link-tile");
          a.href = url;
          a.target = "_blank";
          a.rel = "noopener noreferrer";
          var label = url.replace(/^https?:\/\//, "").replace(/\/$/, "");
          if (label.length > 46) label = label.slice(0, 46) + "\u2026";
          a.appendChild(el("span", "docs-link-label", label));
          linksWrap.appendChild(a);
        });
        if (links.length > 6) {
          linksWrap.appendChild(el("div", "docs-link-more", "+" + (links.length - 6) + " more links"));
        }
        inner.appendChild(linksWrap);
      }

      body.appendChild(inner);
      card.appendChild(body);

      head.addEventListener("click", function () { card.classList.toggle("is-open"); });
      grid.appendChild(card);
    });
  }

  function actionBtn(label, kind, fn) {
    var b = el("button", "docs-act docs-act-" + kind);
    b.textContent = label;
    b.title = label;
    b.addEventListener("click", function (e) {
      e.stopPropagation();
      fn();
    });
    return b;
  }

  function formatBytes(n) {
    if (n < 1024) return n + " B";
    if (n < 1024 * 1024) return (n / 1024).toFixed(1) + " KB";
    return (n / 1024 / 1024).toFixed(1) + " MB";
  }

  function formatCount(n) {
    n = Number(n) || 0;
    if (n >= 1000000) {
      var m = n / 1000000;
      return (Number.isInteger(m) ? m.toFixed(0) : m.toFixed(1).replace(/\.0$/, "")) + "M";
    }
    return n.toLocaleString("en-US");
  }

  /* ---------- doc actions ---------- */

  function getDoc(id) {
    for (var i = 0; i < state.docs.length; i++) {
      if (state.docs[i].id === id) return state.docs[i];
    }
    return null;
  }

  /* Base this app is served from (the cloak injects a <base href> pointing at
     the CDN repo root; otherwise derive it from the page URL). Root-absolute
     list fetches like fetch("/noahs-hub.txt") inside doc pages would otherwise
     resolve against the wrong origin when Chalkle is embedded/cloaked. */
  function appBase() {
    var b = document.querySelector("base");
    if (b && b.getAttribute("href")) return b.getAttribute("href");
    var href = location.href.split("#")[0].split("?")[0];
    return href.slice(0, href.lastIndexOf("/") + 1);
  }

  /* Rewrite root-absolute /x.txt fetches inside a doc to base-relative so they
     resolve against wherever this app is actually hosted. */
  function rebaseListPaths(content) {
    return content.replace(/(["'])\/([A-Za-z0-9._-]+\.txt)\1/g, function (m, q, f) {
      return q + appBase() + f + q;
    });
  }

  function openDocPage(id) {
    var doc = getDoc(id);
    if (!doc) return;
    var content = rebaseListPaths(doc.content || "");
    var win = window.open("about:blank", "_blank");
    if (!win) return;
    if (isSvgDoc(content)) {
      /* SVG cloaks must render as a standalone SVG document (image/svg+xml),
         otherwise the browser parses it as HTML and the cloak breaks. */
      var blobUrl = null;
      try {
        var blob = new Blob([content], { type: "image/svg+xml" });
        blobUrl = URL.createObjectURL(blob);
        win.location.replace(blobUrl);
      } catch (e) {
        if (blobUrl) URL.revokeObjectURL(blobUrl);
        win.close();
        win = window.open("data:image/svg+xml;charset=utf-8," + encodeURIComponent(content), "_blank");
        if (!win) return;
      }
      return;
    }
    win.document.open();
    win.document.write(content);
    win.document.close();
    try {
      var title = doc.title || "Chalkle doc";
      win.document.title = title;
    } catch (e) { /* ignore */ }
  }

  function downloadDoc(id) {
    var doc = getDoc(id);
    if (!doc) return;
    var content = doc.content || "";
    var svg = isSvgDoc(content);
    var mime = svg ? "image/svg+xml" : (isHtmlDoc(content) ? "text/html" : "text/plain");
    var ext = svg ? ".svg" : (isHtmlDoc(content) ? ".html" : ".txt");
    var blob = new Blob([content], { type: mime });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = sanitizeName(doc.title || "doc") + ext;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 400);
  }

  function sanitizeName(s) {
    return String(s || "doc").replace(/[\\/:*?"<>|]/g, "").trim() || "doc";
  }

  function copyDoc(id) {
    var doc = getDoc(id);
    if (!doc) return;
    var text = doc.content || "";
    var done = function () {
      notice("Copied \u201c" + (doc.title || "doc") + "\u201d to clipboard");
    };
    var fail = function () {
      try {
        var ta = document.createElement("textarea");
        ta.value = text;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
        done();
      } catch (e) { /* ignore */ }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, fail);
    } else {
      fail();
    }
  }

  function deleteDoc(id) {
    var doc = getDoc(id);
    if (!doc) return;
    if (!window.confirm("Delete \u201c" + (doc.title || "doc") + "\u201d?")) return;
    state.docs = state.docs.filter(function (d) { return d.id !== id; });
    save();
    render();
    refreshAdminList();
  }

  /* ---------- the edit / create modal ---------- */

  var modal = null;
  var editingId = null;
  var pendingCreate = []; /* queue of {title, content} when multiple files are uploaded */

  function openModal() {
    modal = document.getElementById("docs-modal");
    if (!modal) return;
    modal.hidden = false;
    var title = document.getElementById("docs-edit-title");
    var text = document.getElementById("docs-edit-text");
    var count = document.getElementById("docs-edit-count");
    updateLinkCount(title, text, count);
    if (title) title.focus();
  }

  function close() {
    if (modal) modal.hidden = true;
    editingId = null;
  }

  function updateLinkCount(title, text, count) {
    if (!count || !text) return;
    var links = extractLinks(text.value).length;
    count.textContent = links + (links === 1 ? " link detected" : " links detected");
  }

  function newDoc() {
    editingId = null;
    var title = document.getElementById("docs-edit-title");
    var text = document.getElementById("docs-edit-text");
    if (title) title.value = "";
    if (text) text.value = "";
    openModal();
  }

  function editDoc(id) {
    var doc = getDoc(id);
    if (!doc) return;
    editingId = id;
    var title = document.getElementById("docs-edit-title");
    var text = document.getElementById("docs-edit-text");
    if (title) title.value = doc.title || "";
    if (text) text.value = doc.content || "";
    openModal();
  }

  function onSave() {
    var title = document.getElementById("docs-edit-title");
    var text = document.getElementById("docs-edit-text");
    var name = (title && title.value || "").trim() || "Untitled doc";
    var content = text ? text.value : "";

    if (editingId) {
      var doc = getDoc(editingId);
      if (doc) {
        doc.title = name;
        doc.content = content;
        doc.updated = Date.now();
      }
    } else {
      state.docs.push({
        id: uid(),
        title: name,
        content: content,
        html: isHtmlDoc(content),
        svg: isSvgDoc(content),
        created: Date.now()
      });
    }

    save();
    render();
    refreshAdminList();
    close();
    openNextPendingCreate();
  }

  /* ---------- file uploads ---------- */

  function handleFiles(fileList) {
    if (!isAdmin()) return;
    var files = Array.prototype.slice.call(fileList || []);
    if (!files.length) return;
    pendingCreate = files.map(function (f) {
      return { name: f.name, file: f };
    });
    openNextPendingCreate();
  }

  function openNextPendingCreate() {
    var next = pendingCreate.shift();
    if (!next) return;
    var reader = new FileReader();
    reader.onload = function () {
      var content = String(reader.result || "");
      if (content.length > MAX_TEXT_BYTES) {
        notice("\u201c" + next.name + "\u201d is too big to store (max 1.5 MB).");
        openNextPendingCreate();
        return;
      }
      editingId = null;
      var title = document.getElementById("docs-edit-title");
      var text = document.getElementById("docs-edit-text");
      if (title) title.value = stripExt(next.name);
      if (text) text.value = content;
      openModal();
      var count = document.getElementById("docs-edit-count");
      updateLinkCount(title, text, count);
    };
    reader.onerror = function () {
      notice("Couldn\u2019t read \u201c" + next.name + "\u201d.");
      openNextPendingCreate();
    };
    reader.readAsText(next.file);
  }

  function stripExt(name) {
    var base = String(name || "").replace(/\.[^.]+$/, "");
    return base.trim() || "doc";
  }

  /* ---------- admin panel list ---------- */

  function refreshAdminList() {
    var list = document.getElementById("admin-docs-list");
    if (!list) return;
    list.innerHTML = "";
    var docs = state.docs.slice().sort(function (a, b) {
      return (b.created || 0) - (a.created || 0);
    });
    docs.forEach(function (doc) {
      var row = el("div", "admin-lib-row");
      row.dataset.id = doc.id;

      var info = el("div", "admin-lib-info");
      info.appendChild(el("div", "admin-lib-name", doc.title || "Untitled"));
      var kind = isListDoc(doc) ? "List \u00b7 " : (isSvgDoc(doc.content) ? "SVG \u00b7 " : (isHtmlDoc(doc.content) ? "HTML \u00b7 " : ""));
      var sub = el("div", "admin-lib-sub",
        kind +
        linkCount(doc.content) + " links \u00b7 " + formatBytes(String(doc.content || "").length));
      info.appendChild(sub);
      row.appendChild(info);

      var btns = el("div", "admin-lib-btns");
      btns.appendChild(el("button", "btn-ghost", "Edit"));
      btns.appendChild(el("button", "btn-ghost admin-danger", "Delete"));
      row.appendChild(btns);

      btns.children[0].addEventListener("click", function () { editDoc(doc.id); });
      btns.children[1].addEventListener("click", function () { deleteDoc(doc.id); });

      list.appendChild(row);
    });
    if (!docs.length) {
      list.appendChild(el("div", "admin-lib-empty", "No docs yet \u2014 upload a .txt/.html above or hit New doc."));
    }
  }

  /* ---------- admin visibility ---------- */

  function applyAdminUI() {
    var admin = isAdmin();
    var bar = document.querySelector(".docs-bar");
    if (bar) bar.hidden = !admin;
    var uploads = document.querySelectorAll(".docs-btn-upload");
    for (var i = 0; i < uploads.length; i++) {
      uploads[i].parentNode.hidden = !admin;
    }
    render();
    refreshAdminList();
  }

  /* ---------- default docs (re-seeded if removed) ---------- */

  var DEFAULT_DOCS = [
    {
      title: "Velcro",
      html: true,
      content: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Velcro Production</title>\n    <style>\n        body, html {\n            margin: 0;\n            padding: 0;\n            height: 100%;\n            overflow: hidden;\n        }\n        iframe {\n            width: 100%;\n            height: 100%;\n            border: none;\n        }\n    </style>\n</head>\n<body>\n    <iframe src=\"https://velcro-production.up.railway.app/\"></iframe>\n</body>\n</html>"
    },
    { title: "UGS Files", html: true, contentB64: "" },

    { title: "Pizza Edition", html: true, contentB64: "" },
    { title: "Gitlab", html: true, contentB64: "" },
    { title: "Freezenova", html: true, contentB64: "" },
    { title: "Catclass", html: true, contentB64: "" },
    { title: "Infamous", html: true, contentB64: "" },
    { title: "GUST", html: true, contentB64: "" },
    { title: "UBZone", svg: true, contentB64: "" },
    { title: "Linkmaker", svg: true, contentB64: "" },
    { title: "Tundra", svg: true, contentB64: "" },
    { title: "Cinecloud", svg: true, contentB64: "" },
    { title: "Gnmath", html: true, contentB64: "" },
    { title: "Xcloud", svg: true, contentB64: "" },
    { title: "Synapse", html: true, contentB64: "" },
    { title: "PEAK", html: true, contentB64: "" },
    { title: "Granny 3", html: true, contentB64: "" },
    { title: "Cluster Truck", html: true, contentB64: "" },
    { title: "GTA 3", html: true, contentB64: "" },
    { title: "Discord", html: true, contentB64: "" },
    { title: "Cherri List", html: true, list: true, count: 2500000, contentB64: "" },
    { title: "Crazy Cats", html: true, list: true, count: 999, contentB64: "" },
    { title: "Noahs Tutoring Hub", html: true, list: true, count: 9999, contentB64: "" },
    { title: "NEO OS", html: true, contentB64: "" },
    { title: "Learn Links", html: true, list: true, count: 10000, contentB64: "" },
    { title: "Chalkle Links", html: true, list: true, count: 10000, contentB64: "" },
    { title: "Chalkle Links Gcore", html: true, list: true, count: 10000, contentB64: "" },
    { title: "Chalkle Links Fastly", html: true, list: true, count: 10000, contentB64: "" },

    { title: "100k Opium Links", html: true, list: true, count: 100000, contentB64: "" },
    { title: "P2P Links", html: true, list: true, count: 3000, contentB64: "" }
]

  function seedDefaults() {
    var dirty = false;
    DEFAULT_DOCS.forEach(function (def) {
      var existing = null;
      state.docs.some(function (d) {
        if (String(d.title || "").trim().toLowerCase() === String(def.title).trim().toLowerCase()) {
          existing = d;
          return true;
        }
        return false;
      });
      var content = def.content;
      if (def.contentB64) {
        try { content = atob(def.contentB64); } catch (e) { content = ""; }
      }
      if (!existing) {
        state.docs.push({
          id: uid(),
          title: def.title,
          content: content,
          html: def.html ? true : false,
          svg: def.svg ? true : false,
          list: def.list ? true : false,
          count: def.count || 0,
          created: Date.now()
        });
        dirty = true;
      } else if (def.html !== !!existing.html || def.svg !== !!existing.svg || (!!def.list !== !!existing.list)) {
        // Seed's type changed (e.g. Gnmath SVG -> HTML, or a doc became a list):
        // refresh content + flags
        existing.content = content;
        existing.html = def.html ? true : false;
        existing.svg = def.svg ? true : false;
        existing.list = def.list ? true : false;
        existing.count = def.count || 0;
        dirty = true;
      } else if (def.count && existing.count !== def.count) {
        // Same type but the seed knows the link count now (e.g. a 10k list):
        // refresh just the count so cards can show it.
        existing.count = def.count;
        dirty = true;
      }
    });
    if (dirty) save();
  }

  /* ---------- wiring ---------- */

  function init() {
    var grid = document.getElementById("docs-grid");
    if (!grid) return;

    load();
    seedDefaults();
    try {
      var savedFilter = localStorage.getItem(FILTER_KEY);
      if (["all", "list", "svg", "html"].indexOf(savedFilter) !== -1) state.filter = savedFilter;
    } catch (e) { /* no storage */ }

    var file = document.getElementById("docs-file");
    var sort = document.getElementById("docs-sort");
    var newBtn = document.getElementById("docs-new");

    if (file) {
      file.addEventListener("change", function () {
        if (!isAdmin()) { file.value = ""; return; }
        if (file.files && file.files.length) handleFiles(file.files);
        file.value = "";
      });
    }
    if (sort) sort.addEventListener("change", render);
    if (newBtn) newBtn.addEventListener("click", function () {
      if (isAdmin()) newDoc();
    });

    var filterBtns = document.querySelectorAll("[data-docs-filter]");
    for (var fi = 0; fi < filterBtns.length; fi++) {
      (function (btn) {
        btn.addEventListener("click", function () {
          state.filter = btn.dataset.docsFilter || "all";
          try { localStorage.setItem(FILTER_KEY, state.filter); } catch (e) { /* no storage */ }
          render();
        });
      })(filterBtns[fi]);
    }

    modal = document.getElementById("docs-modal");
    if (modal) {
      var closers = modal.querySelectorAll("[data-docs-close]");
      for (var i = 0; i < closers.length; i++) {
        closers[i    
].addEventListener("click", close);
      }
      var saveBtn = document.getElementById("docs-edit-save");
      var cancelBtn = document.getElementById("docs-edit-cancel");
      var title = document.getElementById("docs-edit-title");
      var text = document.getElementById("docs-edit-text");
      var count = document.getElementById("docs-edit-count");
      if (saveBtn) saveBtn.addEventListener("click", onSave);
      if (cancelBtn) cancelBtn.addEventListener("click", close);
      if (title) title.addEventListener("input", function () { updateLinkCount(title, text, count); });
      if (text) text.addEventListener("input", function () { updateLinkCount(title, text, count); });
    }

    applyAdminUI();
    render();
    refreshAdminList();
  }

  /* Expose a small public API so app.js can keep the Docs panel in sync. */
  window.ChalkleDocs = {
    render: render,
    handleFiles: handleFiles,
    newDoc: newDoc,
    applyAdminUI: applyAdminUI,
    refreshAdminList: refreshAdminList
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
